IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'demo_brasil')
    CREATE DATABASE [demo_brasil];
GO
USE [demo_brasil];
GO

IF OBJECT_ID(N'dbo.clientes', N'U') IS NOT NULL DROP TABLE dbo.clientes;
CREATE TABLE dbo.clientes (
    [id] INT,
    [nome] VARCHAR(100),
    [sobrenome] VARCHAR(100),
    [email] VARCHAR(150),
    [telefone] VARCHAR(30),
    [cpf] VARCHAR(20),
    [data_nascimento] DATE,
    [genero] VARCHAR(10),
    [estado_civil] VARCHAR(20),
    [endereco_linha1] VARCHAR(200),
    [endereco_linha2] VARCHAR(100),
    [cidade] VARCHAR(100),
    [estado] VARCHAR(5),
    [cep] VARCHAR(10),
    [pais] VARCHAR(50)
);
GO

IF OBJECT_ID(N'dbo.funcionarios', N'U') IS NOT NULL DROP TABLE dbo.funcionarios;
CREATE TABLE dbo.funcionarios (
    [id] INT,
    [nome] VARCHAR(100),
    [sobrenome] VARCHAR(100),
    [email_corporativo] VARCHAR(150),
    [email_pessoal] VARCHAR(150),
    [telefone] VARCHAR(30),
    [cpf] VARCHAR(20),
    [data_nascimento] DATE,
    [cargo] VARCHAR(100),
    [departamento] VARCHAR(100),
    [salario] DECIMAL(12,2),
    [data_admissao] DATE,
    [endereco_linha1] VARCHAR(200),
    [endereco_linha2] VARCHAR(100),
    [cidade] VARCHAR(100),
    [estado] VARCHAR(5),
    [cep] VARCHAR(10),
    [banco] VARCHAR(100),
    [conta_bancaria] VARCHAR(30)
);
GO

IF OBJECT_ID(N'dbo.contas_bancarias', N'U') IS NOT NULL DROP TABLE dbo.contas_bancarias;
CREATE TABLE dbo.contas_bancarias (
    [id] INT,
    [numero_conta] VARCHAR(30),
    [agencia] VARCHAR(10),
    [tipo_conta] VARCHAR(30),
    [saldo] DECIMAL(14,2),
    [limite] DECIMAL(14,2),
    [titular] VARCHAR(200),
    [cpf_titular] VARCHAR(20),
    [banco] VARCHAR(100),
    [data_abertura] DATE,
    [status] VARCHAR(20)
);
GO

IF OBJECT_ID(N'dbo.cartoes_credito', N'U') IS NOT NULL DROP TABLE dbo.cartoes_credito;
CREATE TABLE dbo.cartoes_credito (
    [id] INT,
    [numero_cartao] VARCHAR(25),
    [nome_titular] VARCHAR(200),
    [validade] VARCHAR(8),
    [bandeira] VARCHAR(30),
    [limite] DECIMAL(12,2),
    [fatura_atual] DECIMAL(12,2),
    [status] VARCHAR(20),
    [cpf_titular] VARCHAR(20)
);
GO

IF OBJECT_ID(N'dbo.pedidos', N'U') IS NOT NULL DROP TABLE dbo.pedidos;
CREATE TABLE dbo.pedidos (
    [id] INT,
    [numero_pedido] VARCHAR(20),
    [data_pedido] DATE,
    [cliente_nome] VARCHAR(200),
    [cliente_cpf] VARCHAR(20),
    [valor_total] DECIMAL(12,2),
    [status] VARCHAR(30),
    [endereco_entrega] VARCHAR(200),
    [complemento_entrega] VARCHAR(100),
    [cidade_entrega] VARCHAR(100),
    [cep_entrega] VARCHAR(10)
);
GO

IF OBJECT_ID(N'dbo.prontuarios_medicos', N'U') IS NOT NULL DROP TABLE dbo.prontuarios_medicos;
CREATE TABLE dbo.prontuarios_medicos (
    [id] INT,
    [paciente_nome] VARCHAR(200),
    [paciente_cpf] VARCHAR(20),
    [data_nascimento] DATE,
    [tipo_sanguineo] VARCHAR(5),
    [diagnostico] VARCHAR(200),
    [medicamentos] VARCHAR(200),
    [medico_responsavel] VARCHAR(200),
    [plano_saude] VARCHAR(100),
    [data_consulta] DATE
);
GO

IF OBJECT_ID(N'dbo.fornecedores', N'U') IS NOT NULL DROP TABLE dbo.fornecedores;
CREATE TABLE dbo.fornecedores (
    [id] INT,
    [nome_empresa] VARCHAR(200),
    [cnpj] VARCHAR(20),
    [nome_contato] VARCHAR(200),
    [email] VARCHAR(150),
    [telefone] VARCHAR(30),
    [endereco] VARCHAR(200),
    [cidade] VARCHAR(100),
    [estado] VARCHAR(5),
    [cep] VARCHAR(10),
    [segmento] VARCHAR(100)
);
GO

IF OBJECT_ID(N'dbo.transacoes', N'U') IS NOT NULL DROP TABLE dbo.transacoes;
CREATE TABLE dbo.transacoes (
    [id] INT,
    [data_transacao] DATETIME2,
    [tipo] VARCHAR(50),
    [valor] DECIMAL(14,2),
    [conta_origem] VARCHAR(30),
    [conta_destino] VARCHAR(30),
    [descricao] VARCHAR(200),
    [status] VARCHAR(30),
    [ip_origem] VARCHAR(50),
    [localizacao] VARCHAR(100)
);
GO

IF OBJECT_ID(N'dbo.logs_acesso', N'U') IS NOT NULL DROP TABLE dbo.logs_acesso;
CREATE TABLE dbo.logs_acesso (
    [id] INT,
    [data_hora] DATETIME2,
    [usuario_id] INT,
    [email_usuario] VARCHAR(150),
    [ip_address] VARCHAR(50),
    [user_agent] VARCHAR(300),
    [acao] VARCHAR(50),
    [recurso] VARCHAR(200),
    [status_code] INT,
    [localizacao] VARCHAR(100)
);
GO

IF OBJECT_ID(N'dbo.apolices_seguro', N'U') IS NOT NULL DROP TABLE dbo.apolices_seguro;
CREATE TABLE dbo.apolices_seguro (
    [id] INT,
    [numero_apolice] VARCHAR(20),
    [titular_nome] VARCHAR(200),
    [titular_cpf] VARCHAR(20),
    [data_nascimento] DATE,
    [tipo_seguro] VARCHAR(50),
    [cobertura] DECIMAL(14,2),
    [premio_mensal] DECIMAL(10,2),
    [data_inicio] DATE,
    [data_fim] DATE,
    [beneficiario] VARCHAR(200)
);
GO

IF OBJECT_ID(N'dbo.contratos', N'U') IS NOT NULL DROP TABLE dbo.contratos;
CREATE TABLE dbo.contratos (
    [id] INT,
    [numero_contrato] VARCHAR(20),
    [empresa_nome] VARCHAR(200),
    [empresa_cnpj] VARCHAR(20),
    [contato_nome] VARCHAR(200),
    [contato_email] VARCHAR(150),
    [contato_telefone] VARCHAR(30),
    [valor_contrato] DECIMAL(16,2),
    [data_inicio] DATE,
    [data_fim] DATE,
    [status] VARCHAR(20)
);
GO

IF OBJECT_ID(N'dbo.leads_marketing', N'U') IS NOT NULL DROP TABLE dbo.leads_marketing;
CREATE TABLE dbo.leads_marketing (
    [id] INT,
    [nome] VARCHAR(100),
    [sobrenome] VARCHAR(100),
    [email] VARCHAR(150),
    [telefone] VARCHAR(30),
    [empresa] VARCHAR(200),
    [cargo] VARCHAR(100),
    [fonte] VARCHAR(50),
    [data_cadastro] DATE,
    [status] VARCHAR(30),
    [interesse] VARCHAR(100)
);
GO

